def size_text(e: Entry, o: Options) -> str:
    if e.is_dir: return "-"
    n = e.size
    if o.bytes: return f"{n:,}"
    base, symbols = (1024.0, ("", "Ki", "Mi", "Gi", "Ti", "Pi", "Ei")) if o.binary else (1000.0, ("", "k", "M", "G", "T", "P", "E"))
