    for (e, prefix), vals in zip(rows, values):
        bits = [v.rjust(widths[j]) if cols[j][2] == "right" else v.ljust(widths[j]) for j, v in enumerate(vals)]
        out.append(" ".join(bits) + (" " if bits else "") + prefix + shown_name(e, o))
